    lines = inp.strip().split('\n')
    nums = list(map(int, lines[0].split())) if lines and lines[0].strip() else []
    target = int(lines[1]) if len(lines) > 1 else 0
    toks = out.split()
    if len(toks) != 2:
        return False
    try:
        i, j = int(toks[0]), int(toks[1])
    except ValueError:
        return False
    n = len(nums)
    if not (1 <= i <= n and 1 <= j <= n and i != j):
        return False
    return nums[i - 1] + nums[j - 1] == target

