    for a in range(1,4):
        for b in range(1,4):
            for c in range(1,4):
                d = n - a - b - c
                if d < 1 or d > 3: continue
                p = [s[:a], s[a:a+b], s[a+b:a+b+c], s[a+b+c:]]
